//! 🪆️ Cold syntax preparation maps neutral geometry directly into its genuine Drawing owner.
use semio_framework_io_ports::{VectorScene,VectorNode,VectorStyle,VectorTransform,VectorSegment,VectorRgba};
use semio_s_artifact_draw_drawing_model::{snapshot::DrawingSnapshot,DrawingLayerBase,DrawingLayerNode,DrawingGroupBody,DrawingPathBody,DrawingImageBody,DrawingImageAsset,DrawingArtboard,DrawingTransform,DrawingAttributes,FillStyle,StrokeStyle,PathSegment,fill_rule::FillRule,stroke::{StrokeCap,StrokeJoin}};
use std::collections::HashMap;
fn color(c:VectorRgba)->Result<[f64;4],String>{let a=[f64::from(c.r),f64::from(c.g),f64::from(c.b),f64::from(c.a)];if a.iter().all(|v|v.is_finite()){Ok(a)}else{Err("layout.drawing.non-finite".into())}}
fn identity()->DrawingTransform{DrawingTransform{x:0.0,y:0.0,scale_x:1.0,scale_y:1.0,shear:0.0,rotation:0.0}}
fn transform(t:VectorTransform)->Result<DrawingTransform,String>{let(p,q,s)=(t.translation,t.rotation,t.scale);if ![p.x,p.y,p.z,q.x,q.y,q.z,q.w,s.x,s.y,s.z].iter().all(|v|v.is_finite())||p.z!=0.0||q.x!=0.0||q.y!=0.0||s.z!=1.0||(q.z*q.z+q.w*q.w-1.0).abs()>1e-9{return Err("layout.drawing.non-planar-transform".into())}Ok(DrawingTransform{x:p.x,y:p.y,scale_x:s.x,scale_y:s.y,shear:0.0,rotation:2.0*q.z.atan2(q.w)})}
fn segment(s:VectorSegment)->Result<PathSegment,String>{let p=|v:semio_framework_io_ports::VectorPoint2|[v.x,v.y];let s=match s{VectorSegment::MoveTo{to}=>PathSegment::Move{to:p(to)},VectorSegment::LineTo{to}=>PathSegment::Line{to:p(to)},VectorSegment::QuadTo{c,to}=>PathSegment::Quad{ctrl:p(c),to:p(to)},VectorSegment::CubicTo{c1,c2,to}=>PathSegment::Cubic{ctrl1:p(c1),ctrl2:p(c2),to:p(to)},VectorSegment::ArcTo{rx,ry,x_rotation,large_arc,sweep,to}=>PathSegment::Arc{rx,ry,rotation:x_rotation,large_arc,sweep,to:p(to)},VectorSegment::Close=>PathSegment::Close};if semio_s_artifact_draw_drawing_model::valid_path_segment(&s){Ok(s)}else{Err("layout.drawing.path-geometry".into())}}
struct Lift<'a>{control:&'a mut dyn FnMut(usize)->bool,work:usize,ordinal:usize,styles:HashMap<String,VectorStyle>,assets:semio_framework_value::paged::PagedMap<DrawingImageAsset,{usize::MAX}>}
impl Lift<'_>{
 fn tick(&mut self)->Result<(),String>{self.work+=1;if(self.control)(self.work){Ok(())}else{Err("layout.interchange.cancelled".into())}}
 fn base(&mut self,name:String,visible:bool)->DrawingLayerBase{let id=format!("import-{}",self.ordinal);self.ordinal+=1;DrawingLayerBase{id:id.into(),name:name.into(),visible,locked:false,opacity:1.0,blend_mode:"normal".into(),transform:identity(),attributes:DrawingAttributes{fill_rule:FillRule::Nonzero,fill:None,stroke:None}}}
 fn paint(&self,b:&mut DrawingLayerBase,name:Option<String>)->Result<(),String>{let Some(name)=name else{return Ok(())};let s=self.styles.get(&name).ok_or("layout.drawing.style-missing")?;b.attributes.fill=s.fill.map(color).transpose()?.map(|color|FillStyle::Solid{color});b.attributes.stroke=if let Some(c)=s.stroke{let width=s.stroke_width.unwrap_or(1.0);if !width.is_finite()||width<0.0{return Err("layout.drawing.stroke-width".into())}Some(StrokeStyle{color:color(c)?,width,cap:StrokeCap::Butt,join:StrokeJoin::Miter,dash:None})}else{None};if let Some(opacity)=s.opacity{if !opacity.is_finite()||!(0.0..=1.0).contains(&opacity){return Err("layout.drawing.opacity".into())}b.opacity=f64::from(opacity)}Ok(())}
 fn node(&mut self,n:VectorNode,depth:usize)->Result<DrawingLayerNode,String>{self.tick()?;if depth>64{return Err("layout.drawing.depth".into())}let mut base=self.base("Imported".into(),true);Ok(match n{VectorNode::Group{transform:t,children}=>{base.transform=transform(t)?;let mut rows=Vec::with_capacity(children.len());for child in children{rows.push(self.node(child,depth+1)?)}DrawingLayerNode::Group(DrawingGroupBody{base,isolation:false,children:rows.into()})},VectorNode::Path{segments,style}=>{self.paint(&mut base,style)?;let mut rows=Vec::with_capacity(segments.len());for s in segments{self.tick()?;rows.push(segment(s)?)}DrawingLayerNode::Path(DrawingPathBody{base,segments:rows.into()})},VectorNode::Text{..}=>return Err("layout.drawing.text-typography".into()),VectorNode::Image{at,width,height,mime,bytes}=>{if ![at.x,at.y,width,height].iter().all(|v|v.is_finite())||width<=0.0||height<=0.0{return Err("layout.drawing.image-size".into())}if mime!="image/png"{return Err("layout.drawing.image-mime".into())}if bytes.len()<24||&bytes[..8]!=b"\x89PNG\r\n\x1a\n"{return Err("layout.drawing.image-png".into())}let w=u32::from_be_bytes(bytes[16..20].try_into().unwrap());let h=u32::from_be_bytes(bytes[20..24].try_into().unwrap());if w==0||h==0||u64::from(w)*u64::from(h)>16_777_216{return Err("layout.drawing.image-pixels".into())}let image=semio_s_artifact_stdio_png::standards::v1_2::subsets::any::io::project_png(&bytes)?;let count=usize::try_from(u64::from(image.width)*u64::from(image.height)).map_err(|_|"layout.drawing.image-pixels")?;if image.pixels.len()!=count*4{return Err("layout.drawing.image-samples".into())}let mut samples=Vec::with_capacity(count);for(i,p)in image.pixels.chunks_exact(4).enumerate(){if i%256==0{self.tick()?}samples.push([p[0],p[1],p[2],p[3]])}let image_key=format!("image-{}",base.id);self.assets.insert(image_key.clone(),DrawingImageAsset{width:image.width,height:image.height,samples:samples.into()});base.transform.x=at.x;base.transform.y=at.y;DrawingLayerNode::Image(DrawingImageBody{base,image_key:image_key.into(),width,height})}})}
}
/// 📥️ Creates a genuine typed child snapshot outside retained publication; its target identity comes from original authoring input.
pub fn lift_vector_scene(scene:VectorScene,document_id:String,control:&mut dyn FnMut(usize)->bool)->Result<DrawingSnapshot,String>{if document_id.trim().is_empty(){return Err("layout.drawing.identity".into())}if ![scene.canvas.width,scene.canvas.height].iter().all(|v|v.is_finite()&&*v>0.0){return Err("layout.drawing.canvas".into())}let mut cx=Lift{control,work:0,ordinal:0,styles:HashMap::new(),assets:Default::default()};for style in scene.styles{cx.tick()?;if cx.styles.contains_key(&style.name){return Err("layout.drawing.style-duplicate".into())}cx.styles.insert(style.name.clone(),style);}let mut layers=Vec::new();if let Some(c)=scene.canvas.background{let mut base=cx.base("Canvas".into(),true);base.attributes.fill=Some(FillStyle::Solid{color:color(c)?});layers.push(DrawingLayerNode::Path(DrawingPathBody{base,segments:vec![PathSegment::Move{to:[0.0,0.0]},PathSegment::Line{to:[scene.canvas.width,0.0]},PathSegment::Line{to:[scene.canvas.width,scene.canvas.height]},PathSegment::Line{to:[0.0,scene.canvas.height]},PathSegment::Close].into()}))}for layer in scene.layers{cx.tick()?;let base=cx.base(layer.name,layer.visible);layers.push(DrawingLayerNode::Group(DrawingGroupBody{base,isolation:false,children:vec![cx.node(layer.root,0)?].into()}))}Ok(DrawingSnapshot{schema:semio_s_artifact_draw_drawing_model::DRAWING_DOCUMENT_SCHEMA.into(),id:document_id.into(),title:None,layers:layers.into(),assets:cx.assets,artboard:Some(DrawingArtboard{width:scene.canvas.width,height:scene.canvas.height})})}

